      "A team of agronomists, engineers, and data scientists passionate about rural prosperity.": "কৃষিবিদ, প্রকৌশলী এবং তথ্য বিজ্ঞানীদের একটি দল গ্রামীণ সমৃদ্ধি সম্পর্কে উত্সাহী।",
      "financeDataDesc', 'Manage financial records": "financeDataDesc', 'আর্থিক রেকর্ড পরিচালনা করুন",
