      "badgeLive', 'Live": "ব্যাজলাইভ', 'লাইভ",
      "By combining satellite data, government scheme aggregation, and a direct-to-buyer marketplace, we put the power back in the hands of the farmer.": "স্যাটেলাইট ডেটা, সরকারী স্কিম একত্রীকরণ এবং সরাসরি ক্রেতার বাজারের সমন্বয় করে, আমরা কৃষকের হাতে শক্তি ফিরিয়ে দিয়েছি।",
      "Agriculture is the backbone of our economy, yet those who feed us often face the most uncertainty. Unpredictable weather, opaque market prices, and lack of access to credit trap many farmers in a cycle of debt. AgriWise was built to break that cycle.": "কৃষি আমাদের অর্থনীতির মেরুদণ্ড, তবুও যারা আমাদের খাওয়ায় তারা প্রায়শই সবচেয়ে অনিশ্চয়তার সম্মুখীন হয়। অপ্রত্যাশিত আবহাওয়া, অস্বচ্ছ বাজারমূল্য এবং ঋণ পাওয়ার সুযোগের অভাব অনেক কৃষককে ঋণের চক্রে আটকে রাখে। সেই চক্রটি ভাঙতে এগ্রিওয়াইজ তৈরি করা হয়েছিল।",
      "Transparent pricing, secure payments, and unbiased advice for every user.": "প্রতিটি ব্যবহারকারীর জন্য স্বচ্ছ মূল্য, নিরাপদ অর্থপ্রদান এবং নিরপেক্ষ পরামর্শ।",
