      "Process transactions and send related information, including confirmations and invoices.": "লেনদেন প্রক্রিয়া করুন এবং নিশ্চিতকরণ এবং চালান সহ সম্পর্কিত তথ্য পাঠান।",
      "We couldn't find any orders matching your criteria. When buyers purchase your crops, they will appear here.": "আমরা আপনার মানদণ্ডের সাথে মেলে এমন কোনো অর্ডার খুঁজে পাইনি। ক্রেতারা আপনার ফসল ক্রয় করার সময়, তারা এখানে উপস্থিত হবে.",
      "We collect information you provide directly to us, such as when you create or modify your account, request support, or otherwise communicate with us. This information may include: name, email address, phone number, farm location, crop details, and banking information for transaction processing.": "আমরা আপনার সরাসরি আমাদের কাছে প্রদান করা তথ্য সংগ্রহ করি, যেমন আপনি যখন আপনার অ্যাকাউন্ট তৈরি করেন বা পরিবর্তন করেন, সহায়তার অনুরোধ করেন বা অন্যথায় আমাদের সাথে যোগাযোগ করেন। এই তথ্যগুলি অন্তর্ভুক্ত থাকতে পারে: নাম, ইমেল ঠিকানা, ফোন নম্বর, খামারের অবস্থান, ফসলের বিবরণ, এবং লেনদেন প্রক্রিয়াকরণের জন্য ব্যাঙ্কিং তথ্য৷",
