      "If you have any questions about this Privacy Policy, please contact us at privacy@agriwise.com.": "এই গোপনীয়তা নীতি সম্পর্কে আপনার কোন প্রশ্ন থাকলে, অনুগ্রহ করে আমাদের সাথে privacy@agriwise.com এ যোগাযোগ করুন।",
      "We take reasonable measures to help protect information about you from loss, theft, misuse, and unauthorized access, disclosure, alteration, and destruction. All payment data is encrypted and processed by secure third-party payment gateways.": "ক্ষতি, চুরি, অপব্যবহার এবং অননুমোদিত অ্যাক্সেস, প্রকাশ, পরিবর্তন এবং ধ্বংস থেকে আপনার সম্পর্কে তথ্য রক্ষা করতে আমরা যুক্তিসঙ্গত ব্যবস্থা গ্রহণ করি। সমস্ত পেমেন্ট ডেটা এনক্রিপ্ট করা হয় এবং নিরাপদ থার্ড-পার্টি পেমেন্ট গেটওয়ে দ্বারা প্রক্রিয়া করা হয়।",
      "We do not sell your personal information to third parties. We may share information with vendors, consultants, and other service providers who need access to such information to carry out work on our behalf.": "আমরা তৃতীয় পক্ষের কাছে আপনার ব্যক্তিগত তথ্য বিক্রি করি না। আমরা বিক্রেতা, পরামর্শদাতা এবং অন্যান্য পরিষেবা প্রদানকারীদের সাথে তথ্য শেয়ার করতে পারি যাদের আমাদের পক্ষে কাজ করার জন্য এই ধরনের তথ্যে অ্যাক্সেস প্রয়োজন।",
