      "heroTag": "કૃષિમાં ક્રાંતિ",
      "heroTitle1": "ખેતી અને",
      "heroTitle2": "ભવિષ્યની ટેકનોલોજી.",
      "heroDesc": "ખેડૂતોને એઆઈ-આધારિત માહિતી, રીયલ-ટાઇમ બજાર ભાવ અને સરકારી યોજનાઓ સુધી સીધી પહોંચ સાથે સશક્ત બનાવવા.",
      "ctaBadge": "ખેડૂતો માટે મફત",
      "ctaTitle": "તમારો પાક સેકન્ડોમાં લિસ્ટ કરો.",
      "ctaSubtitle": "શ્રેષ્ઠ ભાવે વેચો.",
      "ctaButton": "મારો પાક વેચો",
      "nav_login": "લોગ ઇન",
      "nav_getStarted": "શરૂ કરો",
      "f1_title": "રીયલ-ટાઇમ માર્કેટ ઇન્ટેલિજન્સ",
      "f1_desc": "દેશભરના બજારોમાંથી નવીનતમ પાકની કિંમતો મેળવો. એઆઈ-આધારિત ભાવની આગાહીઓ સાથે યોગ્ય વેચાણના નિર્ણયો લો.",
      "f2_title": "સ્માર્ટ પ્રાઇસીંગ અને ઇન્વેન્ટરી",
      "f2_desc": "તમારી પાકની યાદીનું સંચાલન કરો અને અમારા ગુણવત્તા-આધારિત ભાવ કેલ્ક્યુલેટરનો ઉપયોગ કરીને યોગ્ય વેચાણ કિંમતની ગણતરી કરો.",
      "f3_title": "સરકારી યોજનાઓ",
      "f3_desc": "તમારી ખેતીની પ્રોફાઇલ અનુસાર સબસિડી, ગ્રાન્ટ્સ અને આર્થિક સહાય શોધો અને અરજી કરો. ક્યારેય કોઈ તક ચૂકશો નહીં.",
      "f4_title": "ચોક્કસ હવામાન",
      "f4_desc": "કૃષિ માટે ખાસ ડિઝાઇન કરાયેલા હાઇપર-લોકલ હવામાનની આગાહીઓ. આત્મવિશ્વાસ સાથે તમારી વાવણી અને લણણીની યોજના બનાવો.",
      "trust_joined": "તમારા જિલ્લાના ખેડૂતો આ અઠવાડિયે જોડાયા.",
      "trust_trustedBy": "વિશ્વાસ કરે છે",
