      "To double the income of 10 million farmers by 2030 through technology and direct market access.": "2030 સુધીમાં ટેક્નોલોજી અને સીધી માર્કેટ એક્સેસ દ્વારા 10 મિલિયન ખેડૂતોની આવક બમણી કરવી.",
