      "Aphid/Caterpillar Infestation": "એફિડ/કેટરપિલરનો ઉપદ્રવ",
      "About AgriWise": "AgriWise વિશે",
      "Spray Neem oil or recommended insecticide.": "લીમડાનું તેલ અથવા ભલામણ કરેલ જંતુનાશકનો છંટકાવ કરો.",
      "AgriWise is on a mission to democratize agricultural intelligence. We believe every farmer, regardless of their scale, deserves access to the same market data, financial tools, and technological insights as the biggest players in the industry.": "AgriWise એ કૃષિ બુદ્ધિના લોકશાહીકરણના મિશન પર છે. અમે માનીએ છીએ કે દરેક ખેડૂત, તેમના સ્કેલને ધ્યાનમાં લીધા વિના, ઉદ્યોગના સૌથી મોટા ખેલાડીઓ તરીકે સમાન બજાર ડેટા, નાણાકીય સાધનો અને તકનીકી આંતરદૃષ્ટિની ઍક્સેસને પાત્ર છે.",
      "Our Promise": "અમારું વચન",
