      "Transparent pricing, secure payments, and unbiased advice for every user.": "દરેક વપરાશકર્તા માટે પારદર્શક કિંમતો, સુરક્ષિત ચૂકવણીઓ અને નિષ્પક્ષ સલાહ.",
      "supportTickets', 'Support Tickets": "સપોર્ટ ટિકિટ', 'સપોર્ટ ટિકિટ્સ",
      "Agriculture is the backbone of our economy, yet those who feed us often face the most uncertainty. Unpredictable weather, opaque market prices, and lack of access to credit trap many farmers in a cycle of debt. AgriWise was built to break that cycle.": "કૃષિ એ આપણી અર્થવ્યવસ્થાની કરોડરજ્જુ છે, તેમ છતાં જેઓ આપણને ખવડાવે છે તેઓ ઘણીવાર સૌથી વધુ અનિશ્ચિતતાનો સામનો કરે છે. અણધારી હવામાન, અપારદર્શક બજાર કિંમતો અને ધિરાણની પહોંચનો અભાવ ઘણા ખેડૂતોને દેવાના ચક્રમાં ફસાવે છે. તે ચક્રને તોડવા માટે એગ્રીવાઈઝનું નિર્માણ કરવામાં આવ્યું હતું.",
      "financeDataDesc', 'Manage financial records": "financeDataDesc', 'નાણાકીય રેકોર્ડ મેનેજ કરો",
      "farmingTips', 'Farming Tips": "farmingTips', 'ખેતી ટિપ્સ",
      "By combining satellite data, government scheme aggregation, and a direct-to-buyer marketplace, we put the power back in the hands of the farmer.": "સેટેલાઇટ ડેટા, સરકારી સ્કીમ એકત્રીકરણ અને ડાયરેક્ટ-ટુ-બાયર માર્કેટપ્લેસને સંયોજિત કરીને, અમે ખેડૂતના હાથમાં સત્તા પાછી મૂકી દીધી છે.",
