      "Search by ID, Buyer, or Crop...": "ID, ખરીદનાર અથવા પાક દ્વારા શોધો...",
      "Mark Pending": "બાકી માર્ક કરો",
      "We couldn't find any orders matching your criteria. When buyers purchase your crops, they will appear here.": "અમે તમારા માપદંડ સાથે મેળ ખાતા કોઈપણ ઓર્ડર શોધી શક્યા નથી. જ્યારે ખરીદદારો તમારો પાક ખરીદે છે, ત્યારે તેઓ અહીં દેખાશે.",
      "Manage incoming orders from buyers and track delivery status.": "ખરીદદારો તરફથી આવતા ઓર્ડરનું સંચાલન કરો અને ડિલિવરી સ્થિતિને ટ્રૅક કરો.",
      "We use the information we collect to provide, maintain, and improve our services, such as to:": "અમે એકત્રિત કરીએ છીએ તે માહિતીનો ઉપયોગ અમે અમારી સેવાઓ પ્રદાન કરવા, જાળવણી કરવા અને સુધારવા માટે કરીએ છીએ, જેમ કે:",
      "We collect information you provide directly to us, such as when you create or modify your account, request support, or otherwise communicate with us. This information may include: name, email address, phone number, farm location, crop details, and banking information for transaction processing.": "અમે માહિતી એકત્રિત કરીએ છીએ જે તમે સીધી અમને પ્રદાન કરો છો, જેમ કે જ્યારે તમે તમારું એકાઉન્ટ બનાવો છો અથવા તેમાં ફેરફાર કરો છો, સમર્થનની વિનંતી કરો છો અથવા અન્યથા અમારી સાથે વાતચીત કરો છો. આ માહિતીમાં આ શામેલ હોઈ શકે છે: નામ, ઈમેલ સરનામું, ફોન નંબર, ખેતરનું સ્થાન, પાકની વિગતો અને વ્યવહારની પ્રક્રિયા માટે બેંકિંગ માહિતી.",
