      "Buy Now": "હવે ખરીદો",
      "If you have any questions about this Privacy Policy, please contact us at privacy@agriwise.com.": "જો તમને આ ગોપનીયતા નીતિ વિશે કોઈ પ્રશ્નો હોય, તો કૃપા કરીને privacy@agriwise.com પર અમારો સંપર્ક કરો.",
      "Respond to your comments, questions, and requests and provide customer service.": "તમારી ટિપ્પણીઓ, પ્રશ્નો અને વિનંતીઓનો જવાબ આપો અને ગ્રાહક સેવા પ્રદાન કરો.",
      "4. Sharing of Information": "4. માહિતીની વહેંચણી",
      "Monitor and analyze trends, usage, and activities in connection with our services.": "અમારી સેવાઓના સંબંધમાં વલણો, વપરાશ અને પ્રવૃત્તિઓનું નિરીક્ષણ અને વિશ્લેષણ કરો.",
      "Verified Harvest": "ચકાસાયેલ લણણી",
      "We take reasonable measures to help protect information about you from loss, theft, misuse, and unauthorized access, disclosure, alteration, and destruction. All payment data is encrypted and processed by secure third-party payment gateways.": "અમે તમારા વિશેની માહિતીને નુકસાન, ચોરી, દુરુપયોગ અને અનધિકૃત ઍક્સેસ, જાહેરાત, ફેરફાર અને વિનાશથી સુરક્ષિત કરવામાં સહાય માટે વ્યાજબી પગલાં લઈએ છીએ. તમામ ચુકવણી ડેટા સુરક્ષિત તૃતીય-પક્ષ ચુકવણી ગેટવે દ્વારા એન્ક્રિપ્ટેડ અને પ્રક્રિયા કરવામાં આવે છે.",
      "We do not sell your personal information to third parties. We may share information with vendors, consultants, and other service providers who need access to such information to carry out work on our behalf.": "અમે તમારી અંગત માહિતી તૃતીય પક્ષોને વેચતા નથી. અમે વિક્રેતાઓ, સલાહકારો અને અન્ય સેવા પ્રદાતાઓ સાથે માહિતી શેર કરી શકીએ છીએ જેમને અમારા વતી કાર્ય કરવા માટે આવી માહિતીની ઍક્સેસની જરૂર હોય છે.",
