      "Back": "पीछे",
      "AgriWise is on a mission to democratize agricultural intelligence. We believe every farmer, regardless of their scale, deserves access to the same market data, financial tools, and technological insights as the biggest players in the industry.": "एग्रीवाइज कृषि बुद्धिमत्ता को लोकतांत्रिक बनाने के मिशन पर है। हमारा मानना ​​है कि हर किसान, अपने पैमाने की परवाह किए बिना, उद्योग में सबसे बड़े खिलाड़ियों के समान बाजार डेटा, वित्तीय उपकरण और तकनीकी अंतर्दृष्टि तक पहुंच का हकदार है।",
      "Who We Are": "हम जो हैं",
      "Crop Advisory": "फसल सलाह",
