      "General Nutrient Stress": "सामान्य पोषक तनाव",
      "To double the income of 10 million farmers by 2030 through technology and direct market access.": "प्रौद्योगिकी और सीधी बाजार पहुंच के माध्यम से 2030 तक 10 मिलियन किसानों की आय दोगुनी करना।",
      "manageSchemesDesc', 'Add or edit govt schemes": "मैनेजस्कीम्सडेस्क', 'सरकारी योजनाएं जोड़ें या संपादित करें",
      "A team of agronomists, engineers, and data scientists passionate about rural prosperity.": "कृषिविदों, इंजीनियरों और डेटा वैज्ञानिकों की एक टीम ग्रामीण समृद्धि के प्रति उत्साहित है।",
      "Agriculture is the backbone of our economy, yet those who feed us often face the most uncertainty. Unpredictable weather, opaque market prices, and lack of access to credit trap many farmers in a cycle of debt. AgriWise was built to break that cycle.": "कृषि हमारी अर्थव्यवस्था की रीढ़ है, फिर भी जो हमें खाना खिलाते हैं उन्हें अक्सर सबसे अधिक अनिश्चितता का सामना करना पड़ता है। अप्रत्याशित मौसम, अपारदर्शी बाजार कीमतें और ऋण तक पहुंच की कमी कई किसानों को कर्ज के चक्र में फंसा देती है। उस चक्र को तोड़ने के लिए एग्रीवाइज का निर्माण किया गया था।",
