      "heroDesc": "ರೈತರಿಗೆ ಎಐ-ಆಧಾರಿತ ಮಾಹಿತಿ, ನೈಜ-ಸಮಯದ ಮಾರುಕಟ್ಟೆ ಡೇಟಾ ಮತ್ತು ಸರ್ಕಾರಿ ಯೋಜನೆಗಳಿಗೆ ನೇರ ಪ್ರವೇಶವನ್ನು ನೀಡುವುದು.",
      "ctaBadge": "ರೈತರಿಗೆ ಉಚಿತ",
