      "f1_desc": "ದೇಶಾದ್ಯಂತದ ಮಾರುಕಟ್ಟೆಗಳಿಂದ ಇತ್ತೀಚಿನ ಬೆಳೆಯ ಬೆಲೆಗಳನ್ನು ಪಡೆಯಿರಿ. ಎಐ-ಆಧಾರಿತ ಬೆಲೆ ಮುನ್ಸೂಚನೆಗಳೊಂದಿಗೆ ಸರಿಯಾದ ಮಾರಾಟ ನಿರ್ಧಾರಗಳನ್ನು ತೆಗೆದುಕೊಳ್ಳಿ.",
      "f2_title": "ಸ್ಮಾರ್ಟ್ ಬೆಲೆ ಮತ್ತು ದಾಸ್ತಾನು",
      "f2_desc": "ನಿಮ್ಮ ಬೆಳೆ ಪಟ್ಟಿಯನ್ನು ನಿರ್ವಹಿಸಿ ಮತ್ತು ನಮ್ಮ ಗುಣಮಟ್ಟ ಆಧಾರಿತ ಬೆಲೆ ಕ್ಯಾಲ್ಕುಲೇಟರ್ ಬಳಸಿ ಸರಿಯಾದ ಮಾರಾಟ ಬೆಲೆಯನ್ನು ಲೆಕ್ಕ ಹಾಕಿ.",
      "f3_title": "ಸರ್ಕಾರಿ ಯೋಜನೆಗಳು",
      "f3_desc": "ನಿಮ್ಮ ಕೃಷಿ ಪ್ರೊಫೈಲ್‌ಗೆ ಅನುಗುಣವಾಗಿ ಸಬ್ಸಿಡಿಗಳು, ಅನುದಾನಗಳು ಮತ್ತು ಆರ್ಥಿಕ ಸಹಾಯವನ್ನು ಹುಡುಕಿ ಮತ್ತು ಅರ್ಜಿ ಸಲ್ಲಿಸಿ. ಯಾವುದೇ ಅವಕಾಶವನ್ನು ಕಳೆದುಕೊಳ್ಳಬೇಡಿ.",
      "f4_title": "ನಿಖರವಾದ ಹವಾಮಾನ",
