      "Spray Neem oil or recommended insecticide.": "ಬೇವಿನ ಎಣ್ಣೆ ಅಥವಾ ಶಿಫಾರಸು ಮಾಡಿದ ಕೀಟನಾಶಕವನ್ನು ಸಿಂಪಡಿಸಿ.",
      "Balanced NPK application and consistent irrigation required.": "ಸಮತೋಲಿತ NPK ಅಪ್ಲಿಕೇಶನ್ ಮತ್ತು ಸ್ಥಿರವಾದ ನೀರಾವರಿ ಅಗತ್ಯವಿದೆ.",
      "To double the income of 10 million farmers by 2030 through technology and direct market access.": "ತಂತ್ರಜ್ಞಾನ ಮತ್ತು ನೇರ ಮಾರುಕಟ್ಟೆ ಪ್ರವೇಶದ ಮೂಲಕ 2030 ರ ವೇಳೆಗೆ 10 ಮಿಲಿಯನ್ ರೈತರ ಆದಾಯವನ್ನು ದ್ವಿಗುಣಗೊಳಿಸುವುದು.",
      "AgriWise is on a mission to democratize agricultural intelligence. We believe every farmer, regardless of their scale, deserves access to the same market data, financial tools, and technological insights as the biggest players in the industry.": "ಅಗ್ರಿವೈಸ್ ಕೃಷಿ ಬುದ್ಧಿವಂತಿಕೆಯನ್ನು ಪ್ರಜಾಪ್ರಭುತ್ವಗೊಳಿಸುವ ಉದ್ದೇಶದಲ್ಲಿದೆ. ಪ್ರತಿಯೊಬ್ಬ ರೈತರು, ಅವರ ಪ್ರಮಾಣವನ್ನು ಲೆಕ್ಕಿಸದೆಯೇ, ಉದ್ಯಮದಲ್ಲಿನ ದೊಡ್ಡ ಆಟಗಾರರಂತೆಯೇ ಅದೇ ಮಾರುಕಟ್ಟೆ ಡೇಟಾ, ಹಣಕಾಸು ಪರಿಕರಗಳು ಮತ್ತು ತಾಂತ್ರಿಕ ಒಳನೋಟಗಳಿಗೆ ಪ್ರವೇಶಕ್ಕೆ ಅರ್ಹರು ಎಂದು ನಾವು ನಂಬುತ್ತೇವೆ.",
      "General Nutrient Stress": "ಸಾಮಾನ್ಯ ಪೌಷ್ಟಿಕಾಂಶದ ಒತ್ತಡ",
      "Scheme Assistance": "ಸ್ಕೀಮ್ ನೆರವು",
      "App / Tech Support": "ಅಪ್ಲಿಕೇಶನ್ / ಟೆಕ್ ಬೆಂಬಲ",
      "Our Promise": "ನಮ್ಮ ಭರವಸೆ",
      "Why We Started": "ನಾವು ಏಕೆ ಪ್ರಾರಂಭಿಸಿದ್ದೇವೆ",
      "badgeCore', 'Core": "ಬ್ಯಾಡ್ಜ್‌ಕೋರ್', 'ಕೋರ್",
      "badgeLive', 'Live": "ಬ್ಯಾಡ್ಜ್ ಲೈವ್', 'ಲೈವ್",
      "greeting_morning', 'Good Morning": "ಶುಭಾಶಯ_ಮುಂಜಾನೆ', 'ಶುಭೋದಯ",
      "financeData', 'Finance Data": "financeData', 'ಹಣಕಾಸು ಡೇಟಾ",
      "greeting_afternoon', 'Good Afternoon": "ಶುಭಾಶಯ_ಮಧ್ಯಾಹ್ನ', 'ಶುಭ ಮಧ್ಯಾಹ್ನ",
      "By combining satellite data, government scheme aggregation, and a direct-to-buyer marketplace, we put the power back in the hands of the farmer.": "ಉಪಗ್ರಹ ದತ್ತಾಂಶ, ಸರ್ಕಾರಿ ಯೋಜನೆಗಳ ಒಟ್ಟುಗೂಡಿಸುವಿಕೆ ಮತ್ತು ನೇರವಾಗಿ ಖರೀದಿದಾರರಿಗೆ ಮಾರುಕಟ್ಟೆ ಸ್ಥಳವನ್ನು ಸಂಯೋಜಿಸುವ ಮೂಲಕ, ನಾವು ರೈತರ ಕೈಗೆ ಮತ್ತೆ ಅಧಿಕಾರವನ್ನು ನೀಡುತ್ತೇವೆ.",
      "manageSchemes', 'Manage Schemes": "ನಿರ್ವಹಣೆ ಯೋಜನೆಗಳು', 'ಯೋಜನೆಗಳನ್ನು ನಿರ್ವಹಿಸಿ",
      "farmingTips', 'Farming Tips": "farmingTips', 'ಕೃಷಿ ಸಲಹೆಗಳು",
      "latestUpdates', 'Latest Updates": "ಇತ್ತೀಚಿನ ನವೀಕರಣಗಳು', 'ಇತ್ತೀಚಿನ ನವೀಕರಣಗಳು",
      "greeting_evening', 'Good Evening": "ಶುಭಾಶಯ_ಸಂಜೆ', 'ಶುಭ ಸಂಜೆ",
      "supportTickets', 'Support Tickets": "ಬೆಂಬಲ ಟಿಕೆಟ್‌ಗಳು', 'ಬೆಂಬಲ ಟಿಕೆಟ್‌ಗಳು",
      "manageSchemesDesc', 'Add or edit govt schemes": "manageSchemesDesc', 'ಸರ್ಕಾರಿ ಯೋಜನೆಗಳನ್ನು ಸೇರಿಸಿ ಅಥವಾ ಸಂಪಾದಿಸಿ",
      "farmingTipsDesc', 'Update expert advice": "farmingTipsDesc', 'ತಜ್ಞ ಸಲಹೆಯನ್ನು ನವೀಕರಿಸಿ",
      "latestUpdatesDesc', 'Broadcast news": "ಇತ್ತೀಚಿನ ಅಪ್‌ಡೇಟ್ಸ್‌ಡೆಸ್ಕ್', 'ಪ್ರಸಾರ ಸುದ್ದಿ",
      "financeDataDesc', 'Manage financial records": "financeDataDesc', 'ಹಣಕಾಸು ದಾಖಲೆಗಳನ್ನು ನಿರ್ವಹಿಸಿ",
      "Transparent pricing, secure payments, and unbiased advice for every user.": "ಪ್ರತಿ ಬಳಕೆದಾರರಿಗೆ ಪಾರದರ್ಶಕ ಬೆಲೆ, ಸುರಕ್ಷಿತ ಪಾವತಿಗಳು ಮತ್ತು ಪಕ್ಷಪಾತವಿಲ್ಲದ ಸಲಹೆ.",
      "A team of agronomists, engineers, and data scientists passionate about rural prosperity.": "ಕೃಷಿ ವಿಜ್ಞಾನಿಗಳು, ಎಂಜಿನಿಯರ್‌ಗಳು ಮತ್ತು ಡೇಟಾ ವಿಜ್ಞಾನಿಗಳ ತಂಡವು ಗ್ರಾಮೀಣ ಸಮೃದ್ಧಿಯ ಬಗ್ಗೆ ಉತ್ಸುಕರಾಗಿದ್ದಾರೆ.",
      "Agriculture is the backbone of our economy, yet those who feed us often face the most uncertainty. Unpredictable weather, opaque market prices, and lack of access to credit trap many farmers in a cycle of debt. AgriWise was built to break that cycle.": "ಕೃಷಿ ನಮ್ಮ ಆರ್ಥಿಕತೆಯ ಬೆನ್ನೆಲುಬು, ಆದರೂ ನಮಗೆ ಆಹಾರ ನೀಡುವವರು ಹೆಚ್ಚಾಗಿ ಅನಿಶ್ಚಿತತೆಯನ್ನು ಎದುರಿಸುತ್ತಾರೆ. ಅನಿರೀಕ್ಷಿತ ಹವಾಮಾನ, ಅಪಾರದರ್ಶಕ ಮಾರುಕಟ್ಟೆ ಬೆಲೆಗಳು ಮತ್ತು ಸಾಲದ ಪ್ರವೇಶದ ಕೊರತೆಯು ಅನೇಕ ರೈತರನ್ನು ಸಾಲದ ಚಕ್ರದಲ್ಲಿ ಸಿಲುಕಿಸುತ್ತದೆ. ಆ ಚಕ್ರವನ್ನು ಮುರಿಯಲು ಅಗ್ರಿವೈಸ್ ಅನ್ನು ನಿರ್ಮಿಸಲಾಗಿದೆ.",
