      "f2_desc', 'Manage your crop listings and calculate the perfect selling price using our quality-based price calculator.": "f2_desc', 'ನಿಮ್ಮ ಬೆಳೆ ಪಟ್ಟಿಗಳನ್ನು ನಿರ್ವಹಿಸಿ ಮತ್ತು ನಮ್ಮ ಗುಣಮಟ್ಟ-ಆಧಾರಿತ ಬೆಲೆ ಕ್ಯಾಲ್ಕುಲೇಟರ್ ಅನ್ನು ಬಳಸಿಕೊಂಡು ಪರಿಪೂರ್ಣ ಮಾರಾಟದ ಬೆಲೆಯನ್ನು ಲೆಕ್ಕಾಚಾರ ಮಾಡಿ.",
