      "Search by ID, Buyer, or Crop...": "ID, ಖರೀದಿದಾರ ಅಥವಾ ಕ್ರಾಪ್ ಮೂಲಕ ಹುಡುಕಿ...",
      "We use the information we collect to provide, maintain, and improve our services, such as to:": "ನಮ್ಮ ಸೇವೆಗಳನ್ನು ಒದಗಿಸಲು, ನಿರ್ವಹಿಸಲು ಮತ್ತು ಸುಧಾರಿಸಲು ನಾವು ಸಂಗ್ರಹಿಸುವ ಮಾಹಿತಿಯನ್ನು ನಾವು ಬಳಸುತ್ತೇವೆ, ಉದಾಹರಣೆಗೆ:",
      "Mark Shipped": "ಮಾರ್ಕ್ ರವಾನಿಸಲಾಗಿದೆ",
      "Mark Processing": "ಮಾರ್ಕ್ ಸಂಸ್ಕರಣೆ",
      "No orders found": "ಯಾವುದೇ ಆದೇಶಗಳು ಕಂಡುಬಂದಿಲ್ಲ",
      "We collect information you provide directly to us, such as when you create or modify your account, request support, or otherwise communicate with us. This information may include: name, email address, phone number, farm location, crop details, and banking information for transaction processing.": "ನೀವು ನಮಗೆ ನೇರವಾಗಿ ಒದಗಿಸುವ ಮಾಹಿತಿಯನ್ನು ನಾವು ಸಂಗ್ರಹಿಸುತ್ತೇವೆ, ಉದಾಹರಣೆಗೆ ನೀವು ನಿಮ್ಮ ಖಾತೆಯನ್ನು ರಚಿಸಿದಾಗ ಅಥವಾ ಮಾರ್ಪಡಿಸಿದಾಗ, ಬೆಂಬಲವನ್ನು ವಿನಂತಿಸಿದಾಗ ಅಥವಾ ನಮ್ಮೊಂದಿಗೆ ಸಂವಹನ ನಡೆಸಿದಾಗ. ಈ ಮಾಹಿತಿಯು ಒಳಗೊಂಡಿರಬಹುದು: ಹೆಸರು, ಇಮೇಲ್ ವಿಳಾಸ, ಫೋನ್ ಸಂಖ್ಯೆ, ಕೃಷಿ ಸ್ಥಳ, ಬೆಳೆ ವಿವರಗಳು ಮತ್ತು ವಹಿವಾಟು ಪ್ರಕ್ರಿಯೆಗಾಗಿ ಬ್ಯಾಂಕಿಂಗ್ ಮಾಹಿತಿ.",
      "Manage incoming orders from buyers and track delivery status.": "ಖರೀದಿದಾರರಿಂದ ಒಳಬರುವ ಆದೇಶಗಳನ್ನು ನಿರ್ವಹಿಸಿ ಮತ್ತು ವಿತರಣಾ ಸ್ಥಿತಿಯನ್ನು ಟ್ರ್ಯಾಕ್ ಮಾಡಿ.",
      "Process transactions and send related information, including confirmations and invoices.": "ವಹಿವಾಟುಗಳನ್ನು ಪ್ರಕ್ರಿಯೆಗೊಳಿಸಿ ಮತ್ತು ದೃಢೀಕರಣಗಳು ಮತ್ತು ಇನ್‌ವಾಯ್ಸ್‌ಗಳು ಸೇರಿದಂತೆ ಸಂಬಂಧಿತ ಮಾಹಿತಿಯನ್ನು ಕಳುಹಿಸಿ.",
      "Send you technical notices, updates, security alerts, and support and administrative messages.": "ನಿಮಗೆ ತಾಂತ್ರಿಕ ಸೂಚನೆಗಳು, ನವೀಕರಣಗಳು, ಭದ್ರತಾ ಎಚ್ಚರಿಕೆಗಳು ಮತ್ತು ಬೆಂಬಲ ಮತ್ತು ಆಡಳಿತಾತ್ಮಕ ಸಂದೇಶಗಳನ್ನು ಕಳುಹಿಸಿ.",
      "We couldn't find any orders matching your criteria. When buyers purchase your crops, they will appear here.": "ನಿಮ್ಮ ಮಾನದಂಡಕ್ಕೆ ಹೊಂದಿಕೆಯಾಗುವ ಯಾವುದೇ ಆರ್ಡರ್‌ಗಳನ್ನು ನಾವು ಹುಡುಕಲಾಗಲಿಲ್ಲ. ಖರೀದಿದಾರರು ನಿಮ್ಮ ಬೆಳೆಗಳನ್ನು ಖರೀದಿಸಿದಾಗ, ಅವರು ಇಲ್ಲಿ ಕಾಣಿಸಿಕೊಳ್ಳುತ್ತಾರೆ.",
      "": "",
