      "Grade A (Export Quality)": "ಗ್ರೇಡ್ ಎ (ರಫ್ತು ಗುಣಮಟ್ಟ)",
      "AGRIWISE": "ಅಗ್ರಿವೈಸ್",
      "Respond to your comments, questions, and requests and provide customer service.": "ನಿಮ್ಮ ಕಾಮೆಂಟ್‌ಗಳು, ಪ್ರಶ್ನೆಗಳು ಮತ್ತು ವಿನಂತಿಗಳಿಗೆ ಪ್ರತಿಕ್ರಿಯಿಸಿ ಮತ್ತು ಗ್ರಾಹಕ ಸೇವೆಯನ್ನು ಒದಗಿಸಿ.",
      "We do not sell your personal information to third parties. We may share information with vendors, consultants, and other service providers who need access to such information to carry out work on our behalf.": "ನಿಮ್ಮ ವೈಯಕ್ತಿಕ ಮಾಹಿತಿಯನ್ನು ನಾವು ಮೂರನೇ ವ್ಯಕ್ತಿಗಳಿಗೆ ಮಾರಾಟ ಮಾಡುವುದಿಲ್ಲ. ನಮ್ಮ ಪರವಾಗಿ ಕೆಲಸವನ್ನು ನಿರ್ವಹಿಸಲು ಅಂತಹ ಮಾಹಿತಿಗೆ ಪ್ರವೇಶದ ಅಗತ್ಯವಿರುವ ಮಾರಾಟಗಾರರು, ಸಲಹೆಗಾರರು ಮತ್ತು ಇತರ ಸೇವಾ ಪೂರೈಕೆದಾರರೊಂದಿಗೆ ನಾವು ಮಾಹಿತಿಯನ್ನು ಹಂಚಿಕೊಳ್ಳಬಹುದು.",
      "We take reasonable measures to help protect information about you from loss, theft, misuse, and unauthorized access, disclosure, alteration, and destruction. All payment data is encrypted and processed by secure third-party payment gateways.": "ನಷ್ಟ, ಕಳ್ಳತನ, ದುರುಪಯೋಗ ಮತ್ತು ಅನಧಿಕೃತ ಪ್ರವೇಶ, ಬಹಿರಂಗಪಡಿಸುವಿಕೆ, ಬದಲಾವಣೆ ಮತ್ತು ವಿನಾಶದಿಂದ ನಿಮ್ಮ ಬಗ್ಗೆ ಮಾಹಿತಿಯನ್ನು ರಕ್ಷಿಸಲು ನಾವು ಸಮಂಜಸವಾದ ಕ್ರಮಗಳನ್ನು ತೆಗೆದುಕೊಳ್ಳುತ್ತೇವೆ. ಎಲ್ಲಾ ಪಾವತಿ ಡೇಟಾವನ್ನು ಎನ್‌ಕ್ರಿಪ್ಟ್ ಮಾಡಲಾಗಿದೆ ಮತ್ತು ಸುರಕ್ಷಿತ ಮೂರನೇ ವ್ಯಕ್ತಿಯ ಪಾವತಿ ಗೇಟ್‌ವೇಗಳಿಂದ ಪ್ರಕ್ರಿಯೆಗೊಳಿಸಲಾಗುತ್ತದೆ.",
      "If you have any questions about this Privacy Policy, please contact us at privacy@agriwise.com.": "ಈ ಗೌಪ್ಯತಾ ನೀತಿಯ ಕುರಿತು ನೀವು ಯಾವುದೇ ಪ್ರಶ್ನೆಗಳನ್ನು ಹೊಂದಿದ್ದರೆ, ದಯವಿಟ್ಟು ನಮ್ಮನ್ನು privacy@agriwise.com ನಲ್ಲಿ ಸಂಪರ್ಕಿಸಿ.",
      "Monitor and analyze trends, usage, and activities in connection with our services.": "ನಮ್ಮ ಸೇವೆಗಳಿಗೆ ಸಂಬಂಧಿಸಿದಂತೆ ಪ್ರವೃತ್ತಿಗಳು, ಬಳಕೆ ಮತ್ತು ಚಟುವಟಿಕೆಗಳನ್ನು ಮೇಲ್ವಿಚಾರಣೆ ಮಾಡಿ ಮತ್ತು ವಿಶ್ಲೇಷಿಸಿ.",
