      "PMFBY (Insurance)": "PMFBY (विमा)",
      "My Reports": "माझे अहवाल",
      "About AgriWise": "AgriWise बद्दल",
      "AgriWise is on a mission to democratize agricultural intelligence. We believe every farmer, regardless of their scale, deserves access to the same market data, financial tools, and technological insights as the biggest players in the industry.": "AgriWise कृषी बुद्धिमत्तेचे लोकशाहीकरण करण्याच्या मोहिमेवर आहे. आमचा विश्वास आहे की प्रत्येक शेतकरी, त्यांचे प्रमाण कितीही असले तरी, समान बाजार डेटा, आर्थिक साधने आणि तंत्रज्ञानविषयक अंतर्दृष्टी या उद्योगातील सर्वात मोठे खेळाडू म्हणून प्रवेशास पात्र आहेत.",
