      "Other Inquiry": "इतर चौकशी",
      "A team of agronomists, engineers, and data scientists passionate about rural prosperity.": "कृषीशास्त्रज्ञ, अभियंते आणि डेटा वैज्ञानिकांची टीम ग्रामीण समृद्धीबद्दल उत्कट आहे.",
      "greeting_morning', 'Good Morning": "greeting_morning', 'शुभ सकाळ",
      "badgeCore', 'Core": "बॅजकोर', 'कोर",
      "Agriculture is the backbone of our economy, yet those who feed us often face the most uncertainty. Unpredictable weather, opaque market prices, and lack of access to credit trap many farmers in a cycle of debt. AgriWise was built to break that cycle.": "शेती हा आपल्या अर्थव्यवस्थेचा कणा आहे, तरीही जे आपल्याला पोसतात त्यांना बहुतेक वेळा अनिश्चिततेचा सामना करावा लागतो. अप्रत्याशित हवामान, अपारदर्शक बाजारभाव आणि कर्जाचा अभाव यामुळे अनेक शेतकरी कर्जाच्या चक्रात अडकतात. ते आवर्तन मोडण्यासाठी ॲग्रीवाइज बांधण्यात आली.",
      "manageSchemesDesc', 'Add or edit govt schemes": "मॅनेज स्कीम्सडेस्क', 'सरकारी योजना जोडा किंवा संपादित करा",
      "By combining satellite data, government scheme aggregation, and a direct-to-buyer marketplace, we put the power back in the hands of the farmer.": "सॅटेलाइट डेटा, सरकारी योजना एकत्रीकरण आणि थेट खरेदीदार मार्केटप्लेस एकत्र करून, आम्ही पुन्हा शेतकऱ्याच्या हातात सत्ता दिली.",
