      "greeting_morning', 'Good Morning": "greeting_morning', 'ਸ਼ੁਭ ਸਵੇਰ",
      "By combining satellite data, government scheme aggregation, and a direct-to-buyer marketplace, we put the power back in the hands of the farmer.": "ਸੈਟੇਲਾਈਟ ਡੇਟਾ, ਸਰਕਾਰੀ ਸਕੀਮਾਂ ਦੀ ਇਕੱਤਰਤਾ, ਅਤੇ ਇੱਕ ਸਿੱਧੇ-ਤੋਂ-ਖਰੀਦਦਾਰ ਬਾਜ਼ਾਰ ਨੂੰ ਜੋੜ ਕੇ, ਅਸੀਂ ਕਿਸਾਨ ਦੇ ਹੱਥਾਂ ਵਿੱਚ ਸ਼ਕਤੀ ਵਾਪਸ ਪਾ ਦਿੰਦੇ ਹਾਂ।",
      "Our Promise": "ਸਾਡਾ ਵਾਅਦਾ",
      "Why We Started": "ਅਸੀਂ ਕਿਉਂ ਸ਼ੁਰੂ ਕੀਤਾ",
      "Agriculture is the backbone of our economy, yet those who feed us often face the most uncertainty. Unpredictable weather, opaque market prices, and lack of access to credit trap many farmers in a cycle of debt. AgriWise was built to break that cycle.": "ਖੇਤੀਬਾੜੀ ਸਾਡੀ ਆਰਥਿਕਤਾ ਦੀ ਰੀੜ੍ਹ ਦੀ ਹੱਡੀ ਹੈ, ਫਿਰ ਵੀ ਜੋ ਸਾਨੂੰ ਭੋਜਨ ਦਿੰਦੇ ਹਨ ਉਹ ਅਕਸਰ ਸਭ ਤੋਂ ਵੱਧ ਅਨਿਸ਼ਚਿਤਤਾ ਦਾ ਸਾਹਮਣਾ ਕਰਦੇ ਹਨ। ਅਸੰਭਵ ਮੌਸਮ, ਧੁੰਦਲੀ ਬਾਜ਼ਾਰੀ ਕੀਮਤਾਂ, ਅਤੇ ਕਰਜ਼ੇ ਤੱਕ ਪਹੁੰਚ ਦੀ ਘਾਟ ਬਹੁਤ ਸਾਰੇ ਕਿਸਾਨਾਂ ਨੂੰ ਕਰਜ਼ੇ ਦੇ ਚੱਕਰ ਵਿੱਚ ਫਸਾਉਂਦੀ ਹੈ। ਐਗਰੀਵਾਈਜ਼ ਉਸ ਚੱਕਰ ਨੂੰ ਤੋੜਨ ਲਈ ਬਣਾਇਆ ਗਿਆ ਸੀ।",
