      "trust_joined', 'Farmers in your district joined this week.": "trust_joined', 'ਤੁਹਾਡੇ ਜ਼ਿਲ੍ਹੇ ਦੇ ਕਿਸਾਨ ਇਸ ਹਫ਼ਤੇ ਸ਼ਾਮਲ ਹੋਏ।",
      "f1_desc', 'Get up-to-the-minute crop prices from mandis across the country. Make informed selling decisions with AI-driven price forecasts.": "f1_desc', 'ਦੇਸ਼ ਭਰ ਦੀਆਂ ਮੰਡੀਆਂ ਤੋਂ ਫਸਲਾਂ ਦੇ ਭਾਅ ਪ੍ਰਾਪਤ ਕਰੋ। ਏਆਈ ਦੁਆਰਾ ਸੰਚਾਲਿਤ ਕੀਮਤ ਪੂਰਵ ਅਨੁਮਾਨਾਂ ਦੇ ਨਾਲ ਸੂਚਿਤ ਵਿਕਰੀ ਫੈਸਲੇ ਲਓ।",
      "f4_desc', 'Hyper-local weather forecasts designed for agriculture. Plan your sowing and harvesting with confidence.": "f4_desc', 'ਖੇਤੀਬਾੜੀ ਲਈ ਤਿਆਰ ਕੀਤੇ ਗਏ ਹਾਈਪਰ-ਸਥਾਨਕ ਮੌਸਮ ਦੀ ਭਵਿੱਖਬਾਣੀ। ਭਰੋਸੇ ਨਾਲ ਆਪਣੀ ਬਿਜਾਈ ਅਤੇ ਵਾਢੀ ਦੀ ਯੋਜਨਾ ਬਣਾਓ।",
      "f2_desc', 'Manage your crop listings and calculate the perfect selling price using our quality-based price calculator.": "f2_desc', 'ਆਪਣੀਆਂ ਫਸਲਾਂ ਦੀਆਂ ਸੂਚੀਆਂ ਦਾ ਪ੍ਰਬੰਧਨ ਕਰੋ ਅਤੇ ਸਾਡੇ ਗੁਣਵੱਤਾ-ਆਧਾਰਿਤ ਕੀਮਤ ਕੈਲਕੁਲੇਟਰ ਦੀ ਵਰਤੋਂ ਕਰਕੇ ਸੰਪੂਰਨ ਵਿਕਰੀ ਮੁੱਲ ਦੀ ਗਣਨਾ ਕਰੋ।",
      "AgriWise": "AgriWise",
