      "Manage incoming orders from buyers and track delivery status.": "ਖਰੀਦਦਾਰਾਂ ਤੋਂ ਆਉਣ ਵਾਲੇ ਆਰਡਰ ਪ੍ਰਬੰਧਿਤ ਕਰੋ ਅਤੇ ਡਿਲਿਵਰੀ ਸਥਿਤੀ ਨੂੰ ਟਰੈਕ ਕਰੋ।",
      "2. How We Use Your Information": "2. ਅਸੀਂ ਤੁਹਾਡੀ ਜਾਣਕਾਰੀ ਦੀ ਵਰਤੋਂ ਕਿਵੇਂ ਕਰਦੇ ਹਾਂ",
