      "We use the information we collect to provide, maintain, and improve our services, such as to:": "ਅਸੀਂ ਇਕੱਠੀ ਕੀਤੀ ਜਾਣਕਾਰੀ ਦੀ ਵਰਤੋਂ ਆਪਣੀਆਂ ਸੇਵਾਵਾਂ ਪ੍ਰਦਾਨ ਕਰਨ, ਸਾਂਭ-ਸੰਭਾਲ ਕਰਨ ਅਤੇ ਬਿਹਤਰ ਬਣਾਉਣ ਲਈ ਕਰਦੇ ਹਾਂ, ਜਿਵੇਂ ਕਿ:",
