      "Mark Processing": "ਮਾਰਕ ਪ੍ਰੋਸੈਸਿੰਗ",
      "Send you technical notices, updates, security alerts, and support and administrative messages.": "ਤੁਹਾਨੂੰ ਤਕਨੀਕੀ ਨੋਟਿਸ, ਅੱਪਡੇਟ, ਸੁਰੱਖਿਆ ਚਿਤਾਵਨੀਆਂ, ਅਤੇ ਸਹਾਇਤਾ ਅਤੇ ਪ੍ਰਬੰਧਕੀ ਸੁਨੇਹੇ ਭੇਜੋ।",
      "We couldn't find any orders matching your criteria. When buyers purchase your crops, they will appear here.": "ਅਸੀਂ ਤੁਹਾਡੇ ਮਾਪਦੰਡ ਨਾਲ ਮੇਲ ਖਾਂਦਾ ਕੋਈ ਆਰਡਰ ਨਹੀਂ ਲੱਭ ਸਕੇ। ਜਦੋਂ ਖਰੀਦਦਾਰ ਤੁਹਾਡੀਆਂ ਫਸਲਾਂ ਖਰੀਦਦੇ ਹਨ, ਉਹ ਇੱਥੇ ਦਿਖਾਈ ਦੇਣਗੇ।",
      "We collect information you provide directly to us, such as when you create or modify your account, request support, or otherwise communicate with us. This information may include: name, email address, phone number, farm location, crop details, and banking information for transaction processing.": "ਅਸੀਂ ਉਹ ਜਾਣਕਾਰੀ ਇਕੱਠੀ ਕਰਦੇ ਹਾਂ ਜੋ ਤੁਸੀਂ ਸਿੱਧੇ ਸਾਨੂੰ ਪ੍ਰਦਾਨ ਕਰਦੇ ਹੋ, ਜਿਵੇਂ ਕਿ ਜਦੋਂ ਤੁਸੀਂ ਆਪਣਾ ਖਾਤਾ ਬਣਾਉਂਦੇ ਜਾਂ ਸੋਧਦੇ ਹੋ, ਸਹਾਇਤਾ ਲਈ ਬੇਨਤੀ ਕਰਦੇ ਹੋ, ਜਾਂ ਸਾਡੇ ਨਾਲ ਸੰਚਾਰ ਕਰਦੇ ਹੋ। ਇਸ ਜਾਣਕਾਰੀ ਵਿੱਚ ਇਹ ਸ਼ਾਮਲ ਹੋ ਸਕਦਾ ਹੈ: ਨਾਮ, ਈਮੇਲ ਪਤਾ, ਫ਼ੋਨ ਨੰਬਰ, ਖੇਤ ਦੀ ਸਥਿਤੀ, ਫਸਲ ਦੇ ਵੇਰਵੇ, ਅਤੇ ਲੈਣ-ਦੇਣ ਦੀ ਪ੍ਰਕਿਰਿਆ ਲਈ ਬੈਂਕਿੰਗ ਜਾਣਕਾਰੀ।",
