      "If you have any questions about this Privacy Policy, please contact us at privacy@agriwise.com.": "ਜੇਕਰ ਇਸ ਗੋਪਨੀਯਤਾ ਨੀਤੀ ਬਾਰੇ ਤੁਹਾਡੇ ਕੋਈ ਸਵਾਲ ਹਨ, ਤਾਂ ਕਿਰਪਾ ਕਰਕੇ ਸਾਡੇ ਨਾਲ privacy@agriwise.com 'ਤੇ ਸੰਪਰਕ ਕਰੋ।",
      "We take reasonable measures to help protect information about you from loss, theft, misuse, and unauthorized access, disclosure, alteration, and destruction. All payment data is encrypted and processed by secure third-party payment gateways.": "ਅਸੀਂ ਤੁਹਾਡੇ ਬਾਰੇ ਜਾਣਕਾਰੀ ਨੂੰ ਨੁਕਸਾਨ, ਚੋਰੀ, ਦੁਰਵਰਤੋਂ, ਅਤੇ ਅਣਅਧਿਕਾਰਤ ਪਹੁੰਚ, ਖੁਲਾਸੇ, ਤਬਦੀਲੀ, ਅਤੇ ਤਬਾਹੀ ਤੋਂ ਬਚਾਉਣ ਵਿੱਚ ਮਦਦ ਕਰਨ ਲਈ ਉਚਿਤ ਉਪਾਅ ਕਰਦੇ ਹਾਂ। ਸਾਰੇ ਭੁਗਤਾਨ ਡੇਟਾ ਨੂੰ ਏਨਕ੍ਰਿਪਟ ਕੀਤਾ ਗਿਆ ਹੈ ਅਤੇ ਸੁਰੱਖਿਅਤ ਤੀਜੀ-ਧਿਰ ਭੁਗਤਾਨ ਗੇਟਵੇ ਦੁਆਰਾ ਸੰਸਾਧਿਤ ਕੀਤਾ ਗਿਆ ਹੈ।",
      "We do not sell your personal information to third parties. We may share information with vendors, consultants, and other service providers who need access to such information to carry out work on our behalf.": "ਅਸੀਂ ਤੁਹਾਡੀ ਨਿੱਜੀ ਜਾਣਕਾਰੀ ਤੀਜੀ ਧਿਰ ਨੂੰ ਨਹੀਂ ਵੇਚਦੇ ਹਾਂ। ਅਸੀਂ ਵਿਕਰੇਤਾਵਾਂ, ਸਲਾਹਕਾਰਾਂ, ਅਤੇ ਹੋਰ ਸੇਵਾ ਪ੍ਰਦਾਤਾਵਾਂ ਨਾਲ ਜਾਣਕਾਰੀ ਸਾਂਝੀ ਕਰ ਸਕਦੇ ਹਾਂ ਜਿਨ੍ਹਾਂ ਨੂੰ ਸਾਡੀ ਤਰਫ਼ੋਂ ਕੰਮ ਕਰਨ ਲਈ ਅਜਿਹੀ ਜਾਣਕਾਰੀ ਤੱਕ ਪਹੁੰਚ ਦੀ ਲੋੜ ਹੁੰਦੀ ਹੈ।",
