      "Use copper-based fungicide. Avoid overhead watering.": "செம்பு அடிப்படையிலான பூஞ்சைக் கொல்லியைப் பயன்படுத்தவும். மேல்நிலை நீர்ப்பாசனத்தைத் தவிர்க்கவும்.",
