      "General Nutrient Stress": "பொது ஊட்டச்சத்து அழுத்தம்",
      "App / Tech Support": "பயன்பாடு / தொழில்நுட்ப ஆதரவு",
      "Spray Neem oil or recommended insecticide.": "வேப்ப எண்ணெய் அல்லது பரிந்துரைக்கப்பட்ட பூச்சிக்கொல்லியை தெளிக்கவும்.",
      "KCC (Low Interest)": "KCC (குறைந்த வட்டி)",
      "PMFBY (Insurance)": "PMFBY (காப்பீடு)",
      "About AgriWise": "AgriWise பற்றி",
      "Balanced NPK application and consistent irrigation required.": "சமச்சீர் NPK பயன்பாடு மற்றும் சீரான நீர்ப்பாசனம் தேவை.",
      "To double the income of 10 million farmers by 2030 through technology and direct market access.": "தொழில்நுட்பம் மற்றும் நேரடி சந்தை அணுகல் மூலம் 2030-க்குள் 10 மில்லியன் விவசாயிகளின் வருமானத்தை இரட்டிப்பாக்க வேண்டும்.",
      "AgriWise is on a mission to democratize agricultural intelligence. We believe every farmer, regardless of their scale, deserves access to the same market data, financial tools, and technological insights as the biggest players in the industry.": "AgriWise விவசாய நுண்ணறிவை ஜனநாயகப்படுத்தும் பணியில் உள்ளது. ஒவ்வொரு விவசாயியும், அவர்களின் அளவைப் பொருட்படுத்தாமல், அதே சந்தைத் தரவு, நிதிக் கருவிகள் மற்றும் தொழில்நுட்ப நுண்ணறிவுகளை தொழில்துறையில் மிகப்பெரிய வீரர்களாக அணுகுவதற்கு தகுதியானவர்கள் என்று நாங்கள் நம்புகிறோம்.",
      "Our Promise": "எங்கள் வாக்குறுதி",
      "Why We Started": "நாங்கள் ஏன் தொடங்கினோம்",
      "badgeCore', 'Core": "பேட்ஜ்கோர்', 'கோர்",
      "badgeLive', 'Live": "பேட்ஜ் லைவ்', 'லைவ்",
      "supportTickets', 'Support Tickets": "ஆதரவு டிக்கெட்டுகள்', 'ஆதரவு டிக்கெட்டுகள்",
      "latestUpdates', 'Latest Updates": "சமீபத்திய புதுப்பிப்புகள்', 'சமீபத்திய புதுப்பிப்புகள்",
      "greeting_afternoon', 'Good Afternoon": "வணக்கம்_மதியம்', 'நல்ல மதியம்",
      "greeting_evening', 'Good Evening": "வாழ்த்து_மாலை', 'நல்ல மாலை",
      "A team of agronomists, engineers, and data scientists passionate about rural prosperity.": "வேளாண் வல்லுநர்கள், பொறியாளர்கள் மற்றும் தரவு விஞ்ஞானிகளின் குழு கிராமப்புற செழிப்பில் ஆர்வமாக உள்ளது.",
      "farmingTipsDesc', 'Update expert advice": "farmingTipsDesc', 'புதுப்பிப்பு நிபுணர் ஆலோசனை",
      "latestUpdatesDesc', 'Broadcast news": "சமீபத்திய அப்டேட்ஸ் டெஸ்க்', 'ஒளிபரப்பு செய்திகள்",
      "financeDataDesc', 'Manage financial records": "financeDataDesc', 'நிதி பதிவுகளை நிர்வகி",
      "greeting_morning', 'Good Morning": "வாழ்த்து_காலை', 'காலை வணக்கம்",
      "farmingTips', 'Farming Tips": "farmingTips', 'விவசாய குறிப்புகள்",
      "financeData', 'Finance Data": "financeData', 'நிதித் தரவு",
      "manageSchemesDesc', 'Add or edit govt schemes": "managementSchemesDesc', 'அரசு திட்டங்களைச் சேர்க்கவும் அல்லது திருத்தவும்",
      "Agriculture is the backbone of our economy, yet those who feed us often face the most uncertainty. Unpredictable weather, opaque market prices, and lack of access to credit trap many farmers in a cycle of debt. AgriWise was built to break that cycle.": "விவசாயம் நமது பொருளாதாரத்தின் முதுகெலும்பு, ஆனால் நமக்கு உணவளிப்பவர்கள் பெரும்பாலும் நிச்சயமற்ற தன்மையை எதிர்கொள்கிறார்கள். கணிக்க முடியாத வானிலை, ஒளிபுகா சந்தை விலை, கடன் கிடைக்காததால் பல விவசாயிகள் கடன் சுழலில் சிக்கியுள்ளனர். அக்ரிவைஸ் அந்த சுழற்சியை உடைக்க கட்டப்பட்டது.",
      "manageSchemes', 'Manage Schemes": "மேலாண்மை திட்டங்கள்', 'திட்டங்களை நிர்வகி",
      "By combining satellite data, government scheme aggregation, and a direct-to-buyer marketplace, we put the power back in the hands of the farmer.": "செயற்கைக்கோள் தரவு, அரசாங்கத் திட்டத் தொகுப்பு மற்றும் நேரடியாக வாங்குபவருக்குச் சந்தை ஆகியவற்றை இணைப்பதன் மூலம், அதிகாரத்தை மீண்டும் விவசாயியின் கைகளில் வழங்குகிறோம்.",
      "Transparent pricing, secure payments, and unbiased advice for every user.": "ஒவ்வொரு பயனருக்கும் வெளிப்படையான விலை, பாதுகாப்பான பணம் மற்றும் பக்கச்சார்பற்ற ஆலோசனை.",
