      "f4_desc', 'Hyper-local weather forecasts designed for agriculture. Plan your sowing and harvesting with confidence.": "f4_desc', 'விவசாயத்திற்காக வடிவமைக்கப்பட்ட உயர்-உள்ளூர் வானிலை முன்னறிவிப்புகள். உங்கள் விதைப்பு மற்றும் அறுவடையை நம்பிக்கையுடன் திட்டமிடுங்கள்.",
