      "f2_desc', 'Manage your crop listings and calculate the perfect selling price using our quality-based price calculator.": "f2_desc', 'உங்கள் பயிர் பட்டியல்களை நிர்வகிக்கவும் மற்றும் எங்களின் தரம் சார்ந்த விலைக் கால்குலேட்டரைப் பயன்படுத்தி சரியான விற்பனை விலையைக் கணக்கிடவும்.",
      "f1_desc', 'Get up-to-the-minute crop prices from mandis across the country. Make informed selling decisions with AI-driven price forecasts.": "f1_desc', 'நாடு முழுவதும் உள்ள மண்டிகளில் இருந்து நிமிடத்திற்கு-பயிர் விலைகளைப் பெறுங்கள். AI-உந்துதல் விலை கணிப்புகள் மூலம் தகவலறிந்த விற்பனை முடிவுகளை எடுக்கவும்.",
      "trust_farmers', 'farmers": "நம்பிக்கை_விவசாயிகள்', 'விவசாயிகள்",
      "f3_desc', 'Discover and apply for subsidies, grants, and financial aid tailored to your farming profile. never miss an opportunity.": "f3_desc', 'உங்கள் விவசாய சுயவிவரத்திற்கு ஏற்ப மானியங்கள், மானியங்கள் மற்றும் நிதி உதவிகளை கண்டுபிடித்து விண்ணப்பிக்கவும். ஒரு சந்தர்ப்பத்தையும் தவறவிடாதீர்கள்.",
