      "Process transactions and send related information, including confirmations and invoices.": "பரிவர்த்தனைகளைச் செயல்படுத்தி, உறுதிப்படுத்தல்கள் மற்றும் இன்வாய்ஸ்கள் உட்பட தொடர்புடைய தகவலை அனுப்பவும்.",
      "No orders found": "ஆர்டர்கள் எதுவும் கிடைக்கவில்லை",
