      "Mark Processing": "குறி செயலாக்கம்",
      "Search by ID, Buyer, or Crop...": "ஐடி, வாங்குபவர் அல்லது செதுக்கி தேடுங்கள்...",
      "Mark Shipped": "மார்க் அனுப்பப்பட்டது",
      "We couldn't find any orders matching your criteria. When buyers purchase your crops, they will appear here.": "உங்கள் நிபந்தனைகளுடன் பொருந்தக்கூடிய எந்த ஆர்டர்களையும் எங்களால் கண்டறிய முடியவில்லை. வாங்குபவர்கள் உங்கள் பயிர்களை வாங்கும் போது, ​​அவர்கள் இங்கே தோன்றும்.",
      "We use the information we collect to provide, maintain, and improve our services, such as to:": "எங்கள் சேவைகளை வழங்க, பராமரிக்க மற்றும் மேம்படுத்த, நாங்கள் சேகரிக்கும் தகவலைப் பயன்படுத்துகிறோம்:",
      "Send you technical notices, updates, security alerts, and support and administrative messages.": "தொழில்நுட்ப அறிவிப்புகள், புதுப்பிப்புகள், பாதுகாப்பு விழிப்பூட்டல்கள் மற்றும் ஆதரவு மற்றும் நிர்வாக செய்திகளை உங்களுக்கு அனுப்பவும்.",
      "We collect information you provide directly to us, such as when you create or modify your account, request support, or otherwise communicate with us. This information may include: name, email address, phone number, farm location, crop details, and banking information for transaction processing.": "உங்கள் கணக்கை உருவாக்குவது அல்லது மாற்றுவது, ஆதரவைக் கோருவது அல்லது எங்களுடன் தொடர்புகொள்வது போன்ற நீங்கள் எங்களுக்கு நேரடியாக வழங்கும் தகவல்களை நாங்கள் சேகரிப்போம். இந்தத் தகவலில் பின்வருவன அடங்கும்: பெயர், மின்னஞ்சல் முகவரி, தொலைபேசி எண், பண்ணை இருப்பிடம், பயிர் விவரங்கள் மற்றும் பரிவர்த்தனை செயலாக்கத்திற்கான வங்கித் தகவல்.",
      "": "",
      "Origin": "தோற்றம்",
