      "3. Data Security": "3. தரவு பாதுகாப்பு",
      "If you have any questions about this Privacy Policy, please contact us at privacy@agriwise.com.": "இந்தத் தனியுரிமைக் கொள்கையைப் பற்றி ஏதேனும் கேள்விகள் இருந்தால், privacy@agriwise.com இல் எங்களைத் தொடர்பு கொள்ளவும்.",
      "We do not sell your personal information to third parties. We may share information with vendors, consultants, and other service providers who need access to such information to carry out work on our behalf.": "உங்கள் தனிப்பட்ட தகவல்களை நாங்கள் மூன்றாம் தரப்பினருக்கு விற்க மாட்டோம். எங்கள் சார்பாக வேலையைச் செய்ய, அத்தகைய தகவல்களை அணுக வேண்டிய விற்பனையாளர்கள், ஆலோசகர்கள் மற்றும் பிற சேவை வழங்குநர்களுடன் நாங்கள் தகவலைப் பகிரலாம்.",
