      "M.R.P.:": "எம்.ஆர்.பி.:",
      "Monitor and analyze trends, usage, and activities in connection with our services.": "எங்கள் சேவைகள் தொடர்பான போக்குகள், பயன்பாடு மற்றும் செயல்பாடுகளை கண்காணித்து பகுப்பாய்வு செய்யுங்கள்.",
      "Grade A (Export Quality)": "கிரேடு ஏ (ஏற்றுமதி தரம்)",
      "AGRIWISE": "அக்ரிவைஸ்",
      "We take reasonable measures to help protect information about you from loss, theft, misuse, and unauthorized access, disclosure, alteration, and destruction. All payment data is encrypted and processed by secure third-party payment gateways.": "உங்களைப் பற்றிய தகவல்களை இழப்பு, திருட்டு, தவறான பயன்பாடு மற்றும் அங்கீகரிக்கப்படாத அணுகல், வெளிப்படுத்துதல், மாற்றுதல் மற்றும் அழித்தல் ஆகியவற்றிலிருந்து பாதுகாக்க உதவும் நியாயமான நடவடிக்கைகளை நாங்கள் எடுக்கிறோம். அனைத்து கட்டணத் தரவும் என்க்ரிப்ட் செய்யப்பட்டு பாதுகாப்பான மூன்றாம் தரப்பு கட்டண நுழைவாயில்களால் செயலாக்கப்படுகிறது.",
