      "Spray Neem oil or recommended insecticide.": "వేపనూనె లేదా సిఫార్సు చేసిన క్రిమిసంహారకాలను పిచికారీ చేయండి.",
      "To double the income of 10 million farmers by 2030 through technology and direct market access.": "సాంకేతికత మరియు ప్రత్యక్ష మార్కెట్ యాక్సెస్ ద్వారా 2030 నాటికి 10 మిలియన్ల రైతుల ఆదాయాన్ని రెట్టింపు చేయడం.",
      "AgriWise is on a mission to democratize agricultural intelligence. We believe every farmer, regardless of their scale, deserves access to the same market data, financial tools, and technological insights as the biggest players in the industry.": "అగ్రివైజ్ వ్యవసాయ మేధస్సును ప్రజాస్వామ్యీకరించే లక్ష్యంతో ఉంది. ప్రతి రైతు, వారి స్థాయితో సంబంధం లేకుండా, పరిశ్రమలో అతిపెద్ద ఆటగాళ్ల వలె అదే మార్కెట్ డేటా, ఆర్థిక సాధనాలు మరియు సాంకేతిక అంతర్దృష్టులను యాక్సెస్ చేయడానికి అర్హులని మేము విశ్వసిస్తున్నాము.",
      "Balanced NPK application and consistent irrigation required.": "సమతుల్య NPK అప్లికేషన్ మరియు స్థిరమైన నీటిపారుదల అవసరం.",
      "Why We Started": "మేము ఎందుకు ప్రారంభించాము",
