      "latestUpdates', 'Latest Updates": "తాజా నవీకరణలు', 'తాజా నవీకరణలు",
      "greeting_afternoon', 'Good Afternoon": "గ్రీటింగ్_మధ్యాహ్నం', 'శుభ మధ్యాహ్నం",
      "By combining satellite data, government scheme aggregation, and a direct-to-buyer marketplace, we put the power back in the hands of the farmer.": "శాటిలైట్ డేటా, ప్రభుత్వ స్కీమ్ అగ్రిగేషన్ మరియు డైరెక్ట్-టు-బైయర్ మార్కెట్‌ప్లేస్‌ను కలపడం ద్వారా, మేము అధికారాన్ని తిరిగి రైతు చేతుల్లోకి ఉంచాము.",
      "greeting_morning', 'Good Morning": "గ్రీటింగ్_మార్నింగ్', 'గుడ్ మార్నింగ్",
