      "badgeLive', 'Live": "బ్యాడ్జ్ లైవ్', 'లైవ్",
      "Transparent pricing, secure payments, and unbiased advice for every user.": "ప్రతి వినియోగదారు కోసం పారదర్శక ధర, సురక్షిత చెల్లింపులు మరియు నిష్పాక్షికమైన సలహా.",
      "badgeCore', 'Core": "బ్యాడ్జ్‌కోర్', 'కోర్",
      "farmingTips', 'Farming Tips": "farmingTips', 'వ్యవసాయ చిట్కాలు",
      "greeting_evening', 'Good Evening": "గ్రీటింగ్_ఈవినింగ్', 'శుభ సాయంత్రం",
      "financeData', 'Finance Data": "ఫైనాన్స్ డేటా', 'ఫైనాన్స్ డేటా",
      "manageSchemes', 'Manage Schemes": "మేనేజ్‌స్కీమ్‌లు', 'స్కీమ్‌లను నిర్వహించండి",
      "A team of agronomists, engineers, and data scientists passionate about rural prosperity.": "వ్యవసాయ శాస్త్రవేత్తలు, ఇంజనీర్లు మరియు డేటా శాస్త్రవేత్తల బృందం గ్రామీణ శ్రేయస్సుపై మక్కువ చూపుతుంది.",
      "Agriculture is the backbone of our economy, yet those who feed us often face the most uncertainty. Unpredictable weather, opaque market prices, and lack of access to credit trap many farmers in a cycle of debt. AgriWise was built to break that cycle.": "వ్యవసాయం మన ఆర్థిక వ్యవస్థకు వెన్నెముక, అయినప్పటికీ మనకు ఆహారం అందించే వారు చాలా అనిశ్చితిని ఎదుర్కొంటారు. అనూహ్య వాతావరణం, అస్పష్టమైన మార్కెట్ ధరలు మరియు రుణాలు అందుబాటులో లేకపోవడం చాలా మంది రైతులను అప్పుల చక్రంలో బంధించాయి. ఆ చక్రాన్ని విచ్ఛిన్నం చేయడానికి అగ్రివైజ్ నిర్మించబడింది.",
