      "Privacy Policy": "గోప్యతా విధానం",
      "Mark Pending": "పెండింగ్‌లో ఉన్నట్లు గుర్తించండి",
      "We use the information we collect to provide, maintain, and improve our services, such as to:": "మేము మా సేవలను అందించడానికి, నిర్వహించడానికి మరియు మెరుగుపరచడానికి మేము సేకరించే సమాచారాన్ని ఉపయోగిస్తాము:",
      "Process transactions and send related information, including confirmations and invoices.": "లావాదేవీలను ప్రాసెస్ చేయండి మరియు నిర్ధారణలు మరియు ఇన్‌వాయిస్‌లతో సహా సంబంధిత సమాచారాన్ని పంపండి.",
      "We collect information you provide directly to us, such as when you create or modify your account, request support, or otherwise communicate with us. This information may include: name, email address, phone number, farm location, crop details, and banking information for transaction processing.": "మీరు మీ ఖాతాను సృష్టించడం లేదా సవరించడం, మద్దతును అభ్యర్థించడం లేదా మాతో కమ్యూనికేట్ చేయడం వంటి మీరు మాకు నేరుగా అందించే సమాచారాన్ని మేము సేకరిస్తాము. ఈ సమాచారం వీటిని కలిగి ఉండవచ్చు: పేరు, ఇమెయిల్ చిరునామా, ఫోన్ నంబర్, వ్యవసాయ స్థానం, పంట వివరాలు మరియు లావాదేవీ ప్రాసెసింగ్ కోసం బ్యాంకింగ్ సమాచారం.",
      "Mark Delivered": "మార్క్ డెలివరీ చేయబడింది",
      "We couldn't find any orders matching your criteria. When buyers purchase your crops, they will appear here.": "మేము మీ ప్రమాణాలకు సరిపోలే ఆర్డర్‌లు ఏవీ కనుగొనలేకపోయాము. కొనుగోలుదారులు మీ పంటలను కొనుగోలు చేసినప్పుడు, వారు ఇక్కడ కనిపిస్తారు.",
      "Mark Shipped": "మార్క్ రవాణా చేయబడింది",
